package io.github.polestarcn.companion;
import static org.junit.Assert.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,qualifiers="w360dp-h780dp-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class V096Beta2EffectsTest {
 Context c; @Before public void start(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("preferences",0).edit().clear().commit();}
 @Test public void cycleIncludesOnlySelectedProjectsAndDefaultsAreAbsorption(){assertEquals(21,EffectTestPlan.cases(c).size());EffectTestPlan.save(c,Arrays.asList(0,4));List<EffectTestPlan.Case> plan=EffectTestPlan.cases(c);assertEquals(12,plan.size());assertTrue(plan.stream().allMatch(p->p.scene==0||p.scene==4));EffectTestPlan.save(c,Arrays.asList(7));assertEquals(1,EffectTestPlan.cases(c).size());assertEquals(7,EffectTestPlan.cases(c).get(0).scene);EffectSettings p=new EffectSettings(c);assertTrue(p.airSpheres);assertTrue(p.airAbsorb);assertTrue(p.absorb);assertEquals(52,p.windowRange);assertEquals(20,p.windowFeather);AppPreferences.set(c,"fx_air_direction","through");AppPreferences.set(c,"fx_direction","up");AppPreferences.set(c,"fx_air_shape","streaks");p=new EffectSettings(c);assertFalse(p.airAbsorb||p.absorb||p.airSpheres);EffectSettings.defaults(c);assertTrue(new EffectSettings(c).airAbsorb);assertEquals(21,EffectTestPlan.cases(c).size());}
 @Test public void selectedAutomaticCycleNeverShowsOtherScenesAndCardIsBelowVehicle()throws Exception{EffectTestPlan.save(c,Arrays.asList(7));org.robolectric.android.controller.ActivityController<VehicleEffectsActivity> ctl=Robolectric.buildActivity(VehicleEffectsActivity.class).setup();VehicleEffectsActivity a=ctl.get();View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(780,1073741824));root.layout(0,0,360,780);root.findViewWithTag("effect_test_all").performClick();Shadows.shadowOf(android.os.Looper.getMainLooper()).idleFor(java.time.Duration.ofSeconds(9));root.measure(View.MeasureSpec.makeMeasureSpec(360,1073741824),View.MeasureSpec.makeMeasureSpec(780,1073741824));root.layout(0,0,360,780);View car=root.findViewWithTag("effect_test_preview"),card=root.findViewWithTag("effect_test_charging_card");assertTrue(car.isShown()&&card.isShown());Rect cr=new Rect(),sr=new Rect();car.getGlobalVisibleRect(cr);card.getGlobalVisibleRect(sr);assertFalse(cr+" vs "+sr,Rect.intersects(cr,sr));assertTrue(((TextView)root.findViewWithTag("effect_test_caption")).getText().toString().contains("充电文字框")||((TextView)root.findViewWithTag("effect_test_caption")).getText().toString().contains("Charging-card"));ctl.pause().stop().destroy();}
 @Test public void inwardFeatherIsCachedSoftAndNeverTouchesRoof(){WindowFeatherMask mask=new WindowFeatherMask();Path path=new Path();path.addRect(10,10,90,50,Path.Direction.CW);RectF b=new RectF(0,0,100,60);Bitmap image=mask.get(path,b,100);assertEquals(0,Color.alpha(image.getPixel(9,20)));assertTrue(Color.alpha(image.getPixel(10,20))<Color.alpha(image.getPixel(30,20)));assertSame(image,mask.get(path,b,100));assertSame(image,mask.get(path,b,20));WindowGlowRenderer glow=new WindowGlowRenderer();Bitmap canvas=Bitmap.createBitmap(500,300,Bitmap.Config.ARGB_8888);glow.draw(new Canvas(canvas),new RectF(0,0,500,300),R.drawable.vehicle_top,2,EffectStateController.Mode.HEATING,300,1,52,7,100);assertEquals(0,Color.alpha(canvas.getPixel(250,150)));assertEquals(0,Color.alpha(canvas.getPixel(5,5)));}
 @Test public void chargingCardsDoNotOverlapVehicleAcrossSkinsAndOrientations()throws Exception{AppRegressionTest base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);MainActivity a=(MainActivity)f.get(base);VehicleCoordinator model=VehicleCoordinator.get(a);f=VehicleCoordinator.class.getDeclaredField("signedIn");f.setAccessible(true);f.setBoolean(model,true);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="CHARGE-LAYOUT-FIXTURE";model.snapshot=new VehicleSnapshot("fixture","masked",68,280,12000,"充电中","全部关闭","全部关闭","已关闭","已上锁",System.currentTimeMillis(),"LIVE",false,"关闭","关闭");Method render=MainActivity.class.getDeclaredMethod("render");render.setAccessible(true);try{for(String skin:UiSkin.CHOICES)for(int[] size:new int[][]{{360,780},{780,360}}){UiSkin.set(a,skin);Configuration cfg=new Configuration(a.getResources().getConfiguration());cfg.screenWidthDp=size[0];cfg.screenHeightDp=size[1];a.getResources().updateConfiguration(cfg,a.getResources().getDisplayMetrics());render.invoke(a);View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(size[0],1073741824),View.MeasureSpec.makeMeasureSpec(size[1],1073741824));root.layout(0,0,size[0],size[1]);View car=root.findViewWithTag("polestar_vehicle");Rect cr=new Rect();assertTrue(car.getGlobalVisibleRect(cr));List<View> cards=new ArrayList<>();collect(root,cards);assertFalse(skin,cards.isEmpty());for(View card:cards){Rect sr=new Rect();assertTrue(card.getGlobalVisibleRect(sr));assertFalse(skin+" "+size[0]+" car="+cr+" card="+sr,Rect.intersects(cr,sr));}}}finally{base.stop();}}
 void collect(View v,List<View> out){if(("charging_section".equals(v.getTag())||"charging_section_legacy".equals(v.getTag()))&&v.isShown())out.add(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)collect(((ViewGroup)v).getChildAt(i),out);}
}
